/* Combat buttons - prominent and clear */
.punch-btn,.kick-btn,.guard-btn{
  width:78px;height:62px;border-radius:18px;font-size:14px;font-weight:900;
  border:none;position:relative;transition:all .12s cubic-bezier(.4,0,.2,1);
}
.punch-btn{
  background:linear-gradient(145deg,#c0392b 0%,#8b2526 100%);
  color:#ecf0f1;box-shadow:0 8px 26px #e74c3c4d, inset 0 1px 0 #e8a15d;
  border:2px solid #m; /* will be overridden */
}
.punch-btn::after{content:'';position:absolute;inset:2px;background:linear-gradient(135deg,#f39c10 0%,#e67e22 100%);border-radius:14px;opacity:0;transition:opacity .12s;}
.punch-btn:hover::after,.punch-btn:active::after{opacity:1;}
.punch-btn:active{background:linear-gradient(145deg,#8b2526 0%,#c0392b 100%);transform:scale(.96);box-shadow:0 10px 30px #e74c3c60, inset 0 2px 0 #bdc3c7;}
.punch-btn:focus-visible{outline:3px solid #f1c40f;outline-offset:2px;}

.kick-btn{
  background:linear-gradient(145deg,#d35400 0%,#b33903 100%);
  color:#ecf0f1;box-shadow:0 8px 26px #e67e224d, inset 0 1px 0 #f1c40f;
  border:2px solid #c0392b;
}
.kick-btn::after{content:'';position:absolute;inset:2px;background:linear-gradient(135deg:#f1c40f 0%,#e67e22 100%);border-radius:14px;opacity:0;transition:opacity .12s;}
.kick-btn:hover::after,.kick-btn:active::after{opacity:1;}
.kick-btn:active{background:linear-gradient(145deg,#b33903 0%,#d35400 100%);transform:scale(.96);box-shadow:0 10px 30px #e67e2260, inset 0 2px 0 #bdc3c7;}
.kick-btn:focus-visible{outline:3px solid #f1c40f;outline-offset:2px;}

.guard-btn{
  background:linear-gradient(145deg,#2c3e50 0%,#1a252f 100%);
  color:#ecf0f1;box-shadow:0 8px 26px #2980b94d, inset 0 1px 0 #3498db;
  border:2px solid #2980b9;
}
.guard-btn::after{content:'';position:absolute;inset:2px;background:linear-gradient(135deg:#2ecc71 0%,#27ae60 100%);border-radius:14px;opacity:0;transition:opacity .12s;}
.guard-btn:hover::after,.guard-btn:active::after{opacity:1;}
.guard-btn:active{background:linear-gradient(145deg,#1a252f 0%,#2c3e50 100%);transform:scale(.96);box-shadow:0 10px 30px #2980b960, inset 0 2px 0 #3498db;}
.guard-btn:focus-visible{outline:3px solid #2ecc71;outline-offset:2px;}

.touch-btn{font-weight:800;text-shadow:0 1px 5px #000;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);transition:transform .1s ease;}
.touch-btn:active,.touch-btn.pressed{background:#ff744e;color:#fff;transform:scale(.94)}

